for(const [key,en,ru,kk] of moduleMessages){
 if(catalog.has(key))throw Error('Duplicate component localization key: '+key);
 catalog.set(key,Object.freeze({en,ru,kk}));
}
const sections=new Map();
function section(prefix,language=locale()){
 const code=['ru','en','kk'].includes(language)?language:'en',id=prefix+':'+code;
 if(sections.has(id))return sections.get(id);
 const result={};let count=0;
 for(const key of catalog.keys())if(key.startsWith(prefix+'.')){
  const path=key.slice(prefix.length+1).split('.');let object=result;
  for(let i=0;i<path.length-1;i++){const part=path[i];object=object[part]||(object[part]=/^\d+$/.test(path[i+1])?[]:{})}
  object[path.at(-1)]=message(key,code);count++;
 }
 if(!count)report('missing-namespace',prefix,code);
 function freeze(v){for(const x of Object.values(v))if(x&&typeof x==='object')freeze(x);return Object.freeze(v)}
 const value=freeze(result);sections.set(id,value);return value;
}
function locales(prefix){return Object.freeze(Object.fromEntries(['ru','en','kk'].map(language=>[language,section(prefix,language)])))}
function report(type,key,language,details=''){
 const id=type+':'+language+':'+key+':'+details;
 if(!diagnostics.has(id)&&diagnostics.size<500)diagnostics.set(id,Object.freeze({type,key,language,details}));
}
function message(key,language=locale(),parameters={}){
 const code=['ru','en','kk'].includes(language)?language:'en';
 const row=catalog.get(key),value=row?.[code];
 if(typeof value!=='string'||!value&&!['interface.shell.privacy','interface.header.products.1.goal'].includes(key)){report('missing-translation',key,code);return '⟦'+key+':'+code+'⟧'}
 return value.replace(/\{([A-Za-z][A-Za-z0-9_]*)\}/g,(token,name)=>{
  if(!Object.prototype.hasOwnProperty.call(parameters,name)){report('missing-parameter',key,code,name);return token}
  return String(parameters[name]);
 });
}
// Read-only compatibility map: old Russian labels continue resolving to the
// same semantic entry. Internal IDs, model payloads and drafts are untouched.
const direct=new Map([...aliases].map(([ru,key])=>[ru,catalog.get(key)]));
/* Anchored, context-specific variable diagnostics. Captured item names,
 * amounts, periods and source-field IDs are inserted unchanged: user-entered
 * product names are NEVER run through the UI dictionary. Unknown strings
 * remain in the original language rather than risking a mistranslation. */
